// export default ChatAdmin;
import React, { useState, useEffect } from "react";
import { getMessages, sendMessage, markMessageAsRead } from "../../services/chatService";
import { Avatar } from "@mui/material";
import { getUsers } from "../../services/userService";
import "./AdminChat.css";

const ChatAdmin = () => {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");

  // הבאת רשימת משתמשים ומיון לפי סטטוס קריאה
  useEffect(() => {
    const fetchUsersWithUnreadStatus = async () => {
      try {
        const usersData = await getUsers();
        const unreadPromises = usersData.map(async (user) => {
          const userMessages = await getMessages("Admin", user.Email);
          const hasUnreadMessages = userMessages.some((msg) => !msg.read);
          return { ...user, hasUnreadMessages };
        });
        const usersWithStatus = await Promise.all(unreadPromises);

        // מיון: משתמשים עם הודעות שלא נקראו יהיו בראש הרשימה
        usersWithStatus.sort((a, b) => b.hasUnreadMessages - a.hasUnreadMessages);

        setUsers(usersWithStatus);
      } catch (error) {
        console.error("Error fetching users with unread status:", error);
      }
    };

    fetchUsersWithUnreadStatus();
  }, []);

  // הבאת הודעות וסימון כנקראו
  useEffect(() => {
    if (!selectedUser) return;

    const fetchMessagesAndMarkAsRead = async () => {
      try {
        const data = await getMessages("Admin", selectedUser.Email);
        const unreadMessages = data.filter((msg) => !msg.read);

        for (const msg of unreadMessages) {
          await markMessageAsRead(msg.message_id);
          msg.read = true; // עדכון לוקאלי
        }

        setMessages(data);
      } catch (error) {
        console.error("Error fetching or updating messages:", error);
      }
    };
    fetchMessagesAndMarkAsRead();
  }, [selectedUser]);

  // שליחת הודעה חדשה
  const handleSendMessage = async () => {
    if (!newMessage.trim()) return;

    try {
      const response = await sendMessage("Admin", selectedUser.Email, newMessage);
      const newMsg = {
        message_id: response.message_id,
        sender_id: "Admin",
        receiver_id: selectedUser.Email,
        message_text: newMessage,
        timestamp: new Date(),
        read: false,
      };
      setMessages([...messages, newMsg]);
      setNewMessage("");
    } catch (error) {
      console.error("Error sending message:", error);
    }
  };

  // טיפול בבחירת משתמש
  const handleUserSelection = (user) => {
    const updatedUsers = users.map((u) =>
      u.Email === user.Email ? { ...u, hasUnreadMessages: false } : u
    );
    setUsers(updatedUsers);
    setSelectedUser(user);
  };

  return (
    <div className="chat-admin-container">
      <div className="user-list">
        <h3>משתמשים</h3>
        {users.map((user) => (
          <div
            key={user.Email}
            className={`user-item ${selectedUser?.Email === user.Email ? "active" : ""}`}
            style={{
              fontWeight: user.hasUnreadMessages ? "bold" : "normal",
              backgroundColor: user.hasUnreadMessages ? "#ffe6e6" : "transparent",
            }}
            onClick={() => handleUserSelection(user)}
          >
            <Avatar src={user.Image} />
            {user.Name}
            {user.hasUnreadMessages && <span className="unread-indicator">●</span>}
          </div>
        ))}
      </div>

      <div className="chat-window">
        {selectedUser ? (
          <>
            <h3>צ'אט עם {selectedUser.Name}</h3>
            <div className="chat-messages">
              {messages.map((msg) => (
                <div
                  key={msg.message_id}
                  className={`message ${msg.sender_id === "Admin" ? "message-out" : "message-in"}`}
                >
                  <Avatar
                    className="avatar"
                    src={msg.sender_id === "Admin" ? "/path-to-admin-avatar.png" : selectedUser.Image}
                  />
                  <div className="message-content">
                    <p>{msg.message_text}</p>
                    <div className="message-meta">
                      <span className="timestamp">
                        {new Date(msg.timestamp).toLocaleString()}
                      </span>
                      <span className="read-indicator">
                        {msg.read ? "✓✓" : "✓"}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
            <div className="chat-input">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="הקלד הודעה..."
              />
              <button onClick={handleSendMessage}>שלח</button>
            </div>
          </>
        ) : (
          <p>בחר משתמש מהצד השמאלי כדי להתחיל צ'אט.</p>
        )}
      </div>
    </div>
  );
};

export default ChatAdmin;
