import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Container, Typography, Box, IconButton, Grid, Tooltip
} from '@mui/material';
import { styled } from '@mui/system';
import ZoomInIcon from '@mui/icons-material/ZoomIn';
import EmailIcon from '@mui/icons-material/Email';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import { fetchProduct } from '../../services/productService';


// עיצוב עמוד פרטי מוצר
const ProductDetailContainer = styled(Container)(({ theme }) => ({
  paddingTop: theme.spacing(4),
  paddingBottom: theme.spacing(4),
  direction: 'rtl',
}));

const ProductImage = styled('img')(({ theme }) => ({
  width: '100%',
  height: 'auto',
  borderRadius: '10px',
  boxShadow: '0px 8px 20px rgba(0,0,0,0.2)',
  cursor: 'pointer',
  transition: 'transform 0.3s ease',
  '&:hover': {
    transform: 'scale(1.05)',
  },
}));

const ProductDetailContent = styled(Box)(({ theme }) => ({
  marginTop: theme.spacing(2),
  textAlign: 'right',
}));

const ReturnButton = styled(IconButton)(({ theme }) => ({
  position: 'absolute',
  top: theme.spacing(2),
  left: theme.spacing(2),
  color: theme.palette.primary.main,
  transition: 'color 0.3s ease',
  '&:hover': {
    color: theme.palette.primary.dark,
  },
}));

const ProductDetail = () => {
  const { productId } = useParams();
  const navigate = useNavigate();
  const [product, setProduct] = useState(null);

  useEffect(() => {
    const fetchTheProduct = async () => {
      const fetchedProduct = await fetchProduct(productId);
      setProduct(fetchedProduct);
    };
    fetchTheProduct();
  }, [productId]);

  const handleReturn = () => {
    navigate('/list'); // חזרה לרשימת המוצרים
  };

  const handleEmailClick = () => {
    const subject = `התעניינות במוצר: ${product.Name}`;
    const body = `שלום,\n\nאני מתעניין ברכישת המוצר הזה: ${product.Name}\nמחיר: ₪${product.Price}\n\nאני אשמח לקבל פרטים נוספים.`;
    const email = "s0533144195@gmail.com";
    const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${email}&su=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.open(gmailUrl, '_blank');
  };


  const handleWhatsAppClick = () => {
    const message = `שלום, אני מתעניין ברכישת המוצר הזה: ${product.Name} - ₪${product.Price}`;
    const phoneNumber = "0522223659"; // מספר הוואטסאפ הרצוי
    window.location.href = `https://wa.me/${phoneNumber}?text=${encodeURIComponent(message)}`;
};

  if (!product) {
    return <Typography>טוען...</Typography>;
  }

  return (
    <ProductDetailContainer>
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', marginBottom: 2 }}>
        <ReturnButton onClick={handleReturn}>
          <Tooltip title="חזרה לרשימה">
            <ArrowForwardIosIcon sx={{fontSize:'35px',zIndex:"5",position:"absolute",left:"95vw",top:"15vh"}}/>
          </Tooltip>
        </ReturnButton>
      </Box>
      <Grid container spacing={4}>
        <Grid item xs={12} md={6}>
          <ProductImage
            src={product.Image}
            alt={product.Name}
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <Typography variant="h3" component="h1" gutterBottom>
            {product.Name}
          </Typography>
          <Typography variant="h5" color="text.secondary" gutterBottom>
            ₪{product.Price}
          </Typography>
          <ProductDetailContent>
            <Typography variant="body1" color="text.primary" paragraph>
              {product.More}
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center', marginBottom: 2 }}>
              <Tooltip title="שלח מייל לקבלת פרטים נוספים">
                <IconButton onClick={handleEmailClick} sx={{ marginRight: 2 }}>
                  <EmailIcon />
                </IconButton>
              </Tooltip>
              <Tooltip title="שלח ווטסאפ לקבלת פרטים נוספים">
                <IconButton onClick={handleWhatsAppClick}>
                  <WhatsAppIcon />
                </IconButton>
              </Tooltip>
            </Box>
          </ProductDetailContent>
        </Grid>
      </Grid>
    </ProductDetailContainer>
  );
};

export default ProductDetail;
