import React from 'react';
import { Box, Typography, Avatar, Button } from '@mui/material';
import { styled, keyframes } from '@mui/system';
import avatar from '../../assets/avatar.jpg';
import backgroundImage from '../../assets/about_back.jpg'

const goToList = () => {
    window.location.href = "/StamFront/list";
};

// אנימציית ריחוף עדין
const fadeInUp = keyframes`
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
`;

const AboutSection = styled(Box)({
    backgroundImage: `url(${backgroundImage})`,
    backgroundSize: 'cover',
    backgroundPosition: 'center',
    padding: '100px 20px',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    minHeight: '100vh',
    color: '#3e2723',
    textAlign: 'center',
    fontFamily: 'EFT_Globus Black, sans-serif',
});

const StyledAvatar = styled(Avatar)({
    width: 200,
    height: 200,
    // margin: '20px 0',
    margin:'0 auto',
    backgroundImage: `url(${avatar})`,
    border: '5px solid #8c7b75',
    animation: `${fadeInUp} 1s ease-out`,
});

const Title = styled(Typography)({
    fontSize: '3rem',
    fontWeight: 'bold',
    marginBottom: '20px',
    animation: `${fadeInUp} 1.2s ease-out`,
});

const Paragraph = styled(Typography)({
    fontSize: '1.75rem',
    lineHeight: 1.8,
    maxWidth: '800px',
    margin: '0 auto 30px',
    animation: `${fadeInUp} 1.5s ease-out`,
});

const StyledButton = styled(Button)({
    // backgroundColor: '#8c7b75',
    backgroundColor:'#3e2723',
    color: '#fff',
    padding: '15px 35px',
    borderRadius: '20px',
    fontSize: '1.3rem',
    fontWeight: 'bold',
    boxShadow: '0px 8px 18px rgba(0, 0, 0, 0.3)',
    animation: `${fadeInUp} 2s ease-out`,
    '&:hover': {
        backgroundColor: '#6d4c41',
    },
    textTransform: 'none',
    marginTop: '30px',
});

const About = () => {
    return (
        <AboutSection dir='rtl'>
            <div style={{backgroundColor:'rgba(255, 255, 255, 0.606)',padding:'10px', borderRadius:'15px'}}>
                <StyledAvatar src={avatar} alt="Avatar" />
                <Title variant="h3" dir='rtl'>
                    היי לכם! ברוכים הבאים לעולמי
                </Title>
                <Paragraph variant="body1" dir='rtl'>
                    שמי קובי, נשוי לאישה מדהימה ואבא לילד מתוק. במשך שנתיים למדתי והתאמנתי באומנות הסת"ם
                    תחת המורים הטובים ביותר בארץ ובחו"ל. לאחר מבחנים קשים, קיבלתי תעודת אמן מוסמך
                    מארגון משמרת סת"ם. אני מזמין אתכם להתרשם מהעבודות שלי ולהרגיש את הדיוק וההשקעה בכל יצירה.
                </Paragraph>
                <StyledButton onClick={goToList}>
                    להתרשמות מהעבודות שלי
                </StyledButton>
            </div>
        </AboutSection>
    );
};

export default About;
