const API_URL = 'https://kobistam.onrender.com/api/chat';
const ADMIN_ID="673616ecf71522905e73577d";
// קבלת הודעות בין משתמשים
export async function getMessages(senderId, receiverId) {
  try {
    const response = await fetch(`${API_URL}/messages?sender_id=${senderId}&receiver_id=${receiverId}`);
    if (!response.ok) {
      throw new Error("Network response was not ok");
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error("Error fetching messages:", error);
    throw error;
  }
}

// שליחת הודעה חדשה
export async function sendMessage(senderId, receiverId, messageText) {
  try {
    const response = await fetch(`${API_URL}/send`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        sender_id: senderId,
        receiver_id: receiverId,
        message_text: messageText,
      }),
    });
    if (!response.ok) {
      throw new Error("Network response was not ok");
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error("Error sending message:", error);
    throw error;
  }
}
//update message as read
export async function markMessageAsRead(messageId) {
  try {
    const response = await fetch(`${API_URL}/mark-as-read`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ message_id: messageId }),
    });
    if (!response.ok) {
      throw new Error("Network response was not ok");
    }
    return await response.json();
  } catch (error) {
    console.error("Error marking message as read:", error);
    throw error;
  }
}
