// export default Chat;
import React, { useState, useEffect } from "react";
import { getMessages, sendMessage, markMessageAsRead } from "../../services/chatService";
import Avatar from "@mui/material/Avatar"; // ספריית Material-UI ל-Avatar
import "./Chat.css";

const Chat = () => {
  let senderId, receiverId;
  let avatar = sessionStorage.getItem('picture')
  if (sessionStorage.getItem('email')) {
    senderId = sessionStorage.getItem('email');
    receiverId = "Admin";
  } else if (sessionStorage.getItem("role") === "true") {
    senderId = "Admin";
    receiverId = sessionStorage.getItem('email');
  }

  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");

  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const data = await getMessages(senderId, receiverId);
        setMessages(data);
      } catch (error) {
        console.error("Error fetching messages:", error);
      }
    };
    fetchMessages();
  }, [senderId, receiverId]);

  const handleSendMessage = async () => {
    if (!newMessage.trim()) return;

    try {
      const response = await sendMessage(senderId, receiverId, newMessage);
      const newMsg = {
        message_id: response.message_id,
        sender_id: senderId,
        receiver_id: receiverId,
        message_text: newMessage,
        timestamp: new Date(),
        read: false,
      };
      setMessages([...messages, newMsg]);
      setNewMessage("");
    } catch (error) {
      console.error("Error sending message:", error);
    }
  };

  const handleMarkAsRead = async (msg) => {
    if (!msg.read) {
      try {
        await markMessageAsRead(msg.message_id);
        msg.read = true;
        setMessages([...messages]);
      } catch (error) {
        console.error("Error marking message as read:", error);
      }
    }
  };

  return (
    <div className="chat-container">
      <div className="chat-background"></div>
      <div className="chat-box">
        <div className="chat-messages">
          {messages.map((msg) => (
            <div
              key={msg.message_id}
              className={`message ${msg.sender_id === senderId ? "message-out" : "message-in"}`}
              onClick={() => handleMarkAsRead(msg)}
            >
              <Avatar className="avatar" src={msg.sender_id != "Admin" ? avatar : "K"}
              >
                {/* {msg.sender_id === senderId ? "U" : "A"} */}


              </Avatar>
              <div className="message-content" dir="rtl">
                <p dir="rtl">{msg.message_text}</p>
                <span className="message-timestamp" dir="ltr">
                  {new Date(msg.timestamp).toLocaleString()}
                </span>
                <span className="message-status" dir="ltr">
                  {msg.read ? "✔✔" : "✔"}
                </span>
              </div>
            </div>
          ))}
        </div>
        <div className="chat-input">
          <input
            dir="rtl"
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="הקלד הודעה..."
          />
          <button onClick={handleSendMessage}>שלח</button>
        </div>
      </div>
    </div>
  );
};

export default Chat;
