import React, { useState, useEffect } from 'react';
import { Card, Button, Typography, Input, Row, Col, Skeleton, message, Popconfirm } from 'antd';
import { EditOutlined, DeleteOutlined, PlusOutlined, SearchOutlined, TagFilled } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { deleteProduct, fetchProducts } from '../../services/productService';
import Swal from 'sweetalert2';

const { Meta } = Card;
const { Search } = Input;
const ProductItem = ({ product, onDelete }) => {
  const navigate = useNavigate();
  const isAdmin = () => sessionStorage.getItem('role') === 'true';

  const handleDelete = async (event) => {
    event.stopPropagation(); // מונע את פעולת הניווט
    try {
      await deleteProduct(product._id);
      onDelete(product._id);
      message.success('המוצר נמחק בהצלחה');
    } catch (error) {
      message.error('שגיאה במחיקת המוצר');
    }
  };

  const handleEdit = (event) => {
    event.stopPropagation(); // מונע את פעולת הניווט
    navigate(`/edit-product/${product._id}`);
  };


  const isLoggedIn = () => !!sessionStorage.getItem('name'); // בדיקה אם המשתמש מחובר
  const handleNavigateToDetail = () => {
    if (isLoggedIn()) {
      navigate(`/product/${product._id}`);
    } else {

      Swal.fire({
        icon: 'warning',
        title: 'שימו לב',
        text: '👆🏼בכדי לראות את פרטי המוצר, יש להרשם באמצעות גוגל',
        confirmButtonText: 'הבנתי',
      });
    }
  };
  return (
    <Card
      dir="rtl"
      hoverable
      cover={<img alt={product.Name} src={product.Image} style={{ height: '200px', objectFit: 'cover' }} />}
      actions={[
        isAdmin() && (
          <>
            <EditOutlined onClick={handleEdit} key="edit" />
            <Popconfirm
              onConfirm={(e) => {
                handleDelete(e); // מנע את פעולת הניווט וגם ביצע את המחיקה
              }}
              title="האם אתה בטוח שברצונך למחוק מוצר זה?"
              okText="כן"
              cancelText="לא"
            >
              <DeleteOutlined key="delete" onClick={(e) => e.stopPropagation()} // מנע את התפשטות האירוע
              />
            </Popconfirm>
          </>
        ),
      ]}
      onClick={handleNavigateToDetail} // ניווט לדף פרטי המוצר כאשר לוחצים על הכרטיס כולו
    >
      {product.OnSale && (
        <TagFilled style={{ color: 'red', position: 'absolute', top: 10, left: 10 }}>במבצע</TagFilled>
      )}
      <Meta
        title={product.Name}
        description={
          <>
            <Typography.Text strong>₪{product.Price}</Typography.Text>
            <br />
            <Typography.Text type="secondary">{product.Description}</Typography.Text>
          </>
        }
      />
    </Card>
  );
};

const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [filteredProducts, setFilteredProducts] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const isAdmin = () => sessionStorage.getItem('role') === 'true';

  useEffect(() => {
    const loadProducts = async () => {
      try {
        const data = await fetchProducts();
        setProducts(data);
        setFilteredProducts(data);
      } catch (error) {
        message.error('שגיאה בטעינת המוצרים');
      } finally {
        setLoading(false);
      }
    };

    loadProducts();
  }, []);

  const handleSearch = (value) => {
    setFilteredProducts(
      products.filter((product) =>
        product.Name.toLowerCase().includes(value.toLowerCase())
      )
    );
  };

  return (
    <div style={{ padding: '20px' }}>
      <Row gutter={[16, 16]}>
        <Col span={24} dir='rtl'>
          <Search
            placeholder="חפש לפי שם"
            enterButton={<SearchOutlined color='#3e2723' />}
            enterButtonProps={{
              style: {
                // backgroundColor: '#3e2723', // חום
                color: 'white', // צבע טקסט לבן
                border: 'none', // הסרת גבול הכפתור
                padding: '0 20px', // מרווח פנימי
              },
            }}
            size="large"
            onSearch={handleSearch}
            style={{ maxWidth: '400px', marginBottom: '20px' }}
          />
          {isAdmin() && (<Button
            type="primary"
            icon={<PlusOutlined />}
            onClick={() => navigate('/add-product')}
            style={{ marginBottom: '20px', backgroundColor: '#3e2723', borderRadius: '20px', float: 'right' }}
          >
            הוספת מוצר
          </Button>)}
        </Col>
        {loading ? (
          Array.from({ length: 10 }).map((_, index) => (
            <Col xs={24} sm={12} md={8} key={index}>
              <Skeleton active />
            </Col>
          ))
        ) : (
          filteredProducts.map((product) => (
            <Col xs={12} sm={12} md={8} key={product._id}>
              <ProductItem product={product} onDelete={(id) => setProducts(products.filter((p) => p._id !== id))}
              />

            </Col>
          ))
        )}
      </Row>
    </div>
  );
};

export default ProductList;
